test('moving tasks appends in order, preserves data and updates ownership and summaries', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-move-'));
  const databasePath = join(directory, 'projects.sqlite');
  let server;
  try {
    server = await start(databasePath);
    const request = (path, method = 'GET', body) => fetch(`${server.url}${path}`, {
      method, headers: { 'Content-Type': 'application/json' },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    const createProject = async name => (await request('/api/projects', 'POST', { name })).json();
    const a = await createProject('Source');
    const b = await createProject('Destination');
    const projectPath = p => `/api/projects/${p.id}`;
    const tasksPath = p => `${projectPath(p)}/tasks`;
    const createTask = async (p, title) => (await request(tasksPath(p), 'POST', { title })).json();
    const first = await createTask(a, 'Older ID');
    const remaining = await createTask(a, 'Remaining');
    const existing = await createTask(b, 'Destination first');
    const taskPath = (p, t) => `${tasksPath(p)}/${t.id}`;
    const move = (p, t, destination) => request(taskPath(p, t), 'PATCH', { destination_project_id: destination });
    for (const changes of [{ completed: true }, { priority: 'High' }, { due_date: '0001-01-01' }]) {
      Object.assign(first, await (await request(taskPath(a, first), 'PATCH', changes)).json());
    }
    await request(projectPath(b), 'PATCH', { default_priority: 'Low' });
    await request(projectPath(b), 'PATCH', { name: 'Renamed destination' });
    for (const invalid of [a.id, 0, null, String(b.id), 1.5]) {
      assert.equal((await move(a, first, invalid)).status, 400);
    }
    assert.equal((await move(a, first, 99999)).status, 404);
    assert.equal((await request(taskPath(a, first), 'PATCH', { destination_project_id: b.id, title: 'Mixed' })).status, 400);
    await request(projectPath(b), 'PATCH', { archived: true });
    assert.equal((await move(a, first, b.id)).status, 409);
    await request(projectPath(b), 'PATCH', { archived: false });
    await request(projectPath(a), 'PATCH', { archived: true });
    assert.equal((await move(a, first, b.id)).status, 409);
    await request(projectPath(a), 'PATCH', { archived: false });
    assert.deepEqual(await (await move(a, first, b.id)).json(), first);
    assert.deepEqual(await (await request(tasksPath(a))).json(), [remaining]);
    assert.deepEqual(await (await request(tasksPath(b))).json(), [existing, first]);
    assert.equal((await move(a, first, b.id)).status, 404);
    const source = await (await request(projectPath(a))).json();
    const destination = await (await request(projectPath(b))).json();
    assert.equal(source.total, 1);
    assert.equal(source.completed, 0);
    assert.equal(destination.total, 2);
    assert.equal(destination.completed, 1);
    const newest = await createTask(b, 'Created after move');
    assert.equal(newest.priority, 'Low');
    await server.stop();
    server = await start(databasePath);
    assert.deepEqual(await (await request(tasksPath(b))).json(), [existing, first, newest]);
    assert.deepEqual(await (await move(b, first, a.id)).json(), first);
    assert.deepEqual(await (await request(tasksPath(a))).json(), [remaining, first]);
    // Blank dates and repeated moves use the same append rules.
    assert.deepEqual(await (await move(b, existing, a.id)).json(), existing);
    assert.deepEqual(await (await request(tasksPath(a))).json(), [remaining, first, existing]);
    await server.stop();
    server = await start(databasePath);
    assert.deepEqual(await (await request(tasksPath(a))).json(), [remaining, first, existing]);
    assert.deepEqual(await (await request(tasksPath(b))).json(), [newest]);
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
